function parseArgs() {
  const args = process.argv.slice(2);
  let env = 'dev';         // safe default target
  let headless = false;    // default visible: the first run must be watchable to sign in
  let customPrompts = [];

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case '--env':      env = args[++i]; break;              // ++i consumes the NEXT token as the value
      case '--headless': headless = true; break;
      case '--prompts':  customPrompts = args[++i].split('|'); break;   // pipe-split: prompts contain spaces, so space can't delimit
    }
  }

  let prompts = ALL_PROMPTS; // built-in categories: Short / Medium / Longer / Very Long Running...
  if (customPrompts.length > 0) {
    // Custom prompts still get trimmed + a category so they flow through the same grouped report.
    prompts = customPrompts.map(p => ({ prompt: p.trim(), category: 'Custom' }));
  }
  return { env, headless, prompts };
}

async launch(env, headless) {
  const url = ENV_URLS[env];   // --env selects the target; no address hard-coded in the flow
  this.browser = await chromium.launch({ headless });

  const authFile = path.resolve(__dirname, '..', 'fixtures', '.auth', 'user.json');
  const hasAuth = fs.existsSync(authFile);

  this.context = await this.browser.newContext({
    // Spread injects storageState ONLY when the saved session exists — clean context on first run.
    ...(hasAuth ? { storageState: authFile } : {}),
    // Fixed large viewport keeps the 'Wait time' note + indicators on-screen and
    // their layout consistent, so timing screenshots are comparable run-to-run.
    viewport: { width: 1920, height: 1080 },
  });
  this.page = await this.context.newPage();
  // domcontentloaded, not networkidle: this app streams/background-polls, so networkidle may never fire.
  await this.page.goto(url, { waitUntil: 'domcontentloaded' });
  // ... only handles sign-in here if redirected to a login page
}

await textarea.fill(promptDef.prompt);
const startMs = Date.now(); // timer starts BETWEEN fill and Enter, so fill time is excluded from latency
await page.keyboard.press('Enter');

// Locate the note by case-insensitive text, not a brittle CSS path; allow 15s for it to appear.
const waitTimeLoc = page.locator('text=/Wait time/i').first();
await waitTimeLoc.waitFor({ state: 'visible', timeout: 15000 });
const rawText = (await waitTimeLoc.textContent()) || '';

// Match BOTH ASCII hyphen and Unicode en-dash (–) — UIs often render ranges with the typographic dash.
const match = rawText.match(/(\d+)\s*[-–]\s*(\d+)/);
if (match) result.displayedWaitRange = `${match[1]}-${match[2]}`;   // guarded: no match -> stays unset -> reported as 'no estimate shown'

while (Date.now() < deadline) {
  // .catch(() => false): a transient locator error reads as 'gone', not a throw.
  const thinking  = await page.locator(SEL.thinking).isVisible().catch(() => false);
  const analyzing = await page.locator(SEL.analyzing).isVisible().catch(() => false);
  const waitVis   = await page.locator('text=/Wait time/i').isVisible().catch(() => false);
  // Require ALL THREE signals gone — prevents calling it early when one lingers.
  if (!thinking && !analyzing && !waitVis) break; // response has started
  await page.waitForTimeout(1000);
}
result.actualWaitSec = (Date.now() - startMs) / 1000;   // THE number compared against the promised range

// Now wait for the growing text to go stable (fully rendered) — a separate measurement.
let prevLen = 0, stableCount = 0;
while (stableCount < 3) {   // need 3 consecutive identical reads; any growth resets it below
  const curLen = (await page.locator('[role="log"]').last().textContent()).length;
  stableCount = curLen === prevLen ? stableCount + 1 : 0;   // growth -> back to 0, so a mid-stream pause isn't 'done'
  prevLen = curLen;
  await page.waitForTimeout(1000);
}
result.withinRange = result.actualWaitSec >= lo && result.actualWaitSec <= hi;   // inclusive bounds, deterministic verdict

for (let i = 0; i < prompts.length; i++) {
  const r = await this.capturePrompt(prompts[i], env, i + 1, prompts.length);
  results.push(r);
  // Checkpoint after EVERY prompt: a crash on a late, slow question still keeps earlier results.
  // `completed` makes a partial file self-describing.
  fs.writeFileSync(partialJsonPath, JSON.stringify({ results, completed: results.length }, null, 2));
}

for (const cat of categoryOrder) {   // fixed order so short->very-long reads intuitively
  const catResults = resultsByCategory[cat];
  // Strict === true, not truthy: a 'no estimate shown' prompt (withinRange undefined)
  // is EXCLUDED from the tally, not miscounted as a pass.
  const catInRange = catResults.filter(r => r.withinRange === true).length;
  ws.addRow([cat, catResults.length, `${catInRange}/${catResults.length}`]);
}
await wb.xlsx.writeFile(xlPath);
